import re

_NUMBER_RE = re.compile(r"^-?\d+$")


class StackUnderflowError(Exception):
    pass


def _is_number(token):
    return bool(_NUMBER_RE.match(token))


def _underflow():
    raise StackUnderflowError("Insufficient number of items in stack")


def _execute(token, stack):
    if token == "+":
        if len(stack) < 2:
            _underflow()
        stack[-2] += stack.pop()
    elif token == "-":
        if len(stack) < 2:
            _underflow()
        stack[-2] -= stack.pop()
    elif token == "*":
        if len(stack) < 2:
            _underflow()
        stack[-2] *= stack.pop()
    elif token == "/":
        if len(stack) < 2:
            _underflow()
        divisor = stack.pop()
        if divisor == 0:
            raise ZeroDivisionError("divide by zero")
        dividend = stack.pop()
        quotient = abs(dividend) // abs(divisor)
        if (dividend < 0) ^ (divisor < 0):
            quotient = -quotient
        stack.append(quotient)
    elif token == "dup":
        if not stack:
            _underflow()
        stack.append(stack[-1])
    elif token == "drop":
        if not stack:
            _underflow()
        stack.pop()
    elif token == "swap":
        if len(stack) < 2:
            _underflow()
        stack[-1], stack[-2] = stack[-2], stack[-1]
    elif token == "over":
        if len(stack) < 2:
            _underflow()
        stack.append(stack[-2])
    else:
        raise ValueError("undefined operation")


def evaluate(input_data):
    stack = []
    definitions = {}

    for line in input_data:
        tokens = line.split()
        i = 0
        while i < len(tokens):
            token = tokens[i].lower()
            if token == ":":
                if i + 1 >= len(tokens):
                    raise ValueError("illegal operation")
                name = tokens[i + 1].lower()
                if _is_number(name):
                    raise ValueError("illegal operation")
                body = []
                i += 2
                while i < len(tokens) and tokens[i].lower() != ";":
                    body.append(tokens[i].lower())
                    i += 1
                if i >= len(tokens):
                    raise ValueError("illegal operation")
                # Expand the definition immediately so that words referenced
                # by it keep the meaning they had at definition time.
                expanded = []
                for body_token in body:
                    if _is_number(body_token):
                        expanded.append(body_token)
                    elif body_token in definitions:
                        expanded.extend(definitions[body_token])
                    else:
                        expanded.append(body_token)
                definitions[name] = expanded
                i += 1
            elif _is_number(token):
                stack.append(int(token))
            elif token in definitions:
                for body_token in definitions[token]:
                    _execute(body_token, stack)
            else:
                _execute(token, stack)
            i += 1

    return stack
```

